def git(*args: str) -> str:
    return subprocess.check_output(["git", *args], text=True).strip()

def main() -> int:
    root = Path.cwd().resolve()
    try:
        branch = git("branch", "--show-current")
        main_sha = git("rev-parse", "main")
    except Exception as exc:
        raise SystemExit(f"Git preflight failed: {exc}")
    if branch != WORKING_BRANCH:
        raise SystemExit(f"Wrong branch: {branch}; expected {WORKING_BRANCH}")
    if main_sha != APPROVED_BASE:
        raise SystemExit(f"Main drift: {main_sha}; expected {APPROVED_BASE}")
    files = json.loads(zlib.decompress(base64.b85decode(PAYLOAD.encode())).decode("utf-8"))
    written = []
    for rel, content in files.items():
        path = (root / rel).resolve()
        if root not in path.parents:
            raise SystemExit(f"Refusing path escape: {rel}")
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists() and path.read_text(encoding="utf-8") != content:
            raise SystemExit(f"Refusing to overwrite different content: {rel}")
        if not path.exists():
            path.write_text(content, encoding="utf-8")
            written.append(rel)
    print(json.dumps({
        "task_id": TASK_ID,
        "repository": REPOSITORY,
        "approved_base": APPROVED_BASE,
        "working_branch": WORKING_BRANCH,
        "approval_command": APPROVAL_COMMAND,
        "payload_sha256": PAYLOAD_SHA256,
        "files_total": len(files),
        "files_written": written,
        "implementation_performed": False,
        "next_command": "python tools/validate_g01.py --workspace .gwc/tasks/SCRUM-203 --gate G2_EXECUTION --json"
    }, indent=2))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
